import json

def solve(data):
    pattern = data['pattern']
    text = data['text']

    def match(i, j):
        if i == len(pattern) and j == len(text):
            return True
        if i < len(pattern) and j == len(text):
            return False
        if pattern[i] == '?' or pattern[i] == text[j]:
            return match(i+1, j+1)
        if pattern[i] == '*':
            return match(i+1, j) or (j < len(text) and match(i, j+1))
        return False

    return match(0, 0)

# Test cases
test_cases = [
    {"input": {"pattern": "*", "text": ""}, "expected": True},
    {"input": {"pattern": "a?", "text": "ab"}, "expected": True},
    {"input": {"pattern": "a*f", "text": "abcdef"}, "expected": True},
    {"input": {"pattern": "a*d", "text": "abc"}, "expected": False},
]

for tc in test_cases:
    result = solve(tc["input"])
    assert result == tc["expected"], f"Failed for {tc}: expected {tc['expected']}, got {result}"
print("All tests passed!")
